DROP DATABASE IF EXISTS wordle;

CREATE DATABASE wordle DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE wordle;

CREATE TABLE categorias (
    id INT AUTO_INCREMENT,
    nombre VARCHAR(30) NOT NULL,
    descripcion VARCHAR(100),
    PRIMARY KEY (id),
    UNIQUE (nombre)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4;

CREATE TABLE usuarios (
    id INT AUTO_INCREMENT,
    nombre VARCHAR(30) NOT NULL,
    victorias INT DEFAULT 0,
    partidas_jugadas INT DEFAULT 0,
    racha_actual INT DEFAULT 0,
    mejor_racha INT DEFAULT 0,
    fecha_registro DATETIME DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE (nombre)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4;

CREATE TABLE palabras_4 (
    id INT AUTO_INCREMENT,
    palabra CHAR(4) NOT NULL,
    categoria_id INT,
    dificultad INT DEFAULT 3,
    PRIMARY KEY (id),
    UNIQUE (palabra),
    FOREIGN KEY (categoria_id) REFERENCES categorias(id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4;

CREATE TABLE palabras_5 (
    id INT AUTO_INCREMENT,
    palabra CHAR(5) NOT NULL,
    categoria_id INT,
    dificultad INT DEFAULT 3,
    PRIMARY KEY (id),
    UNIQUE (palabra),
    FOREIGN KEY (categoria_id) REFERENCES categorias(id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4;

CREATE TABLE palabras_6 (
    id INT AUTO_INCREMENT,
    palabra CHAR(6) NOT NULL,
    categoria_id INT,
    dificultad INT DEFAULT 3,
    PRIMARY KEY (id),
    UNIQUE (palabra),
    FOREIGN KEY (categoria_id) REFERENCES categorias(id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4;

CREATE TABLE partidas (
    id INT AUTO_INCREMENT,
    usuario_id INT NOT NULL,
    palabra_texto VARCHAR(10) NOT NULL,
    longitud INT NOT NULL,
    intentos INT NOT NULL,
    victoria BOOLEAN NOT NULL,
    tiempo_segundos INT DEFAULT 0,
    fecha DATETIME DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    FOREIGN KEY (usuario_id) REFERENCES usuarios(id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4;






